package com.coffeeshop.model;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.List;public final class DocumentModels{private DocumentModels(){}public record Order(long id,String number,String customer,LocalDateTime completedAt,BigDecimal total){@Override public String toString(){return number+" · "+total;}}public record Document(long id,long orderId,String orderNumber,String number,String type,LocalDateTime issuedAt,String issuedBy,BigDecimal subtotal,BigDecimal discount,BigDecimal tax,BigDecimal total,String customer,String business,String taxNumber,String address){}public record Catalog(List<Order>orders,List<Document>documents){public Catalog{orders=List.copyOf(orders);documents=List.copyOf(documents);}}}
